package dev.zomboid.mts;
import java.util.*;
public final class VehicleControls {
 static String p="minecrafttransportsimulator.";static Map<Object,Object> readings=new WeakHashMap<>();
 static Object player(){return R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"clientInterface"),"getClientPlayer");}
 static boolean driver(Object v){Object player=player();if(player==null)return false;Object seat=R.call(player,"getEntityRiding");return seat!=null&&seat.getClass().getSimpleName().equals("PartSeat")&&R.get(seat,"vehicleOn")==v&&R.yes(R.get(R.get(seat,"placementDefinition"),"isController"));}
 static void set(Object variable,double value){R.call(R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface"),"sendToServer",R.make(p+"packets.instances.PacketEntityVariableSet",variable,value));}
 public static void setup(Object gui){int x=((Number)R.get(gui,"guiLeft")).intValue(),y=((Number)R.get(gui,"guiTop")).intValue();R.call(Mechanics.class,"label",gui,x+18,y+16,"CONTROLES DEL VEHICULO",1f,R.get(R.type(p+"baseclasses.ColorRGB"),"WHITE"));String[][] buttons={{"lock","Bloquear / desbloquear"},{"doors","Abrir / cerrar puertas"},{"windows","Subir / bajar ventanas"},{"trunk","Abrir maletera"},{"maintenance","Estado del coche"},{"panel","Motor y controles originales"},{"hood","Abrir / cerrar capo"}};for(int i=0;i<buttons.length;i++)R.call(gui,"addComponent",R.make("dev.zomboid.mts.VehicleButton",gui,x+18+(i%2)*230,y+45+(i/2)*34,210,buttons[i][0],buttons[i][1]));}
 public static void action(Object gui,String action){if(action.startsWith("service-")){FamilyWorkshop.action(gui,action);return;}Object v=R.get(gui,"vehicle");if(!driver(v)&&(!action.equals("hood")||!R.yes(R.call(Inspection.class,"allowed",v,player()))))return;if(action.equals("hood")){Set<String> vars=new LinkedHashSet<>();for(Object o:(List<?>)R.get(R.get(R.get(v,"definition"),"rendering"),"animatedObjects"))for(Object a:(List<?>)R.get(o,"animations")){String n=Objects.toString(R.get(a,"variable"),"");if(n.contains("hood")||n.contains("bonnet"))vars.add(n);}boolean opened=vars.stream().anyMatch(n->R.yes(R.get(R.call(v,"getOrCreateVariable",n),"isActive")));for(String n:vars)set(R.call(v,"getOrCreateVariable",n),opened?0:1);return;}if(action.equals("maintenance")){R.call(gui,"close");set(R.call(v,"getOrCreateVariable","pz_inspect_request"),1);return;}if(action.equals("panel")){R.call(gui,"close");R.make(p+"guis.instances.GUIPanel",v);return;}if(action.equals("lock")){Object var=R.get(v,"lockedVar");set(var,R.yes(R.get(var,"isActive"))?0:1);return;}if(action.equals("windows")){if("quad".equals(R.get(R.get(v,"definition"),"systemName")))return;Object var=R.call(v,"getOrCreateVariable","pz_windows_open");set(var,R.yes(R.get(var,"isActive"))?0:1);return;}if(action.equals("doors")){if(R.yes(R.get(R.get(v,"lockedVar"),"isActive")))return;Set<String> names=new LinkedHashSet<>();for(Object o:(List<?>)R.get(R.get(R.get(v,"definition"),"rendering"),"animatedObjects"))for(Object a:(List<?>)R.get(o,"animations")){String name=Objects.toString(R.get(a,"variable"),"");if(name.startsWith("door_")&&!name.contains("hood")&&!name.contains("trunk"))names.add(name);}boolean any=names.stream().anyMatch(n->R.yes(R.get(R.call(v,"getOrCreateVariable",n),"isActive")));for(String n:names)set(R.call(v,"getOrCreateVariable",n),any?0:1);return;}if(action.equals("trunk")){if(R.yes(R.get(R.get(v,"lockedVar"),"isActive")))return;for(Object part:(Collection<?>)R.get(v,"allParts"))if("zomboid_trunk".equals(R.get(R.get(part,"definition"),"systemName"))){Collection<?> boxes=(Collection<?>)R.get(part,"collisionBoxes");if(boxes.isEmpty())return;R.call(gui,"close");Object packets=R.get(R.type(p+"mcinterface.InterfaceManager"),"packetInterface"),box=boxes.iterator().next(),player=player();R.call(packets,"sendToServer",R.make(p+"packets.instances.PacketEntityInteract",part,player,box,false,true));R.call(packets,"sendToServer",R.make(p+"packets.instances.PacketEntityInteract",part,player,box,false,false));return;}}}
 public static void dashboard(Object gui){Object v=R.get(gui,"vehicle");if(!Mechanics.car(v))return;Object label=R.make(p+"guis.components.GUIComponentLabel",((Number)R.get(gui,"guiLeft")).intValue()+12,((Number)R.get(gui,"guiTop")).intValue()+29,R.get(R.type(p+"baseclasses.ColorRGB"),"WHITE"),"",R.get(R.type(p+"rendering.RenderText$TextAlignment"),"LEFT_ALIGNED"),1f);R.set(label,"ignoreGUILightingState",true);R.call(gui,"addComponent",label);readings.put(gui,label);}
 public static void dashboardState(Object gui){Object label=readings.get(gui);if(label==null)return;Object v=R.get(gui,"vehicle"),engine=((Collection<?>)R.get(v,"engines")).stream().findFirst().orElse(null);double rpm=engine==null?0:R.num(R.get(engine,"rpm")),speed=R.num(R.get(v,"velocity"))*72;R.set(label,"text",String.format("%.0f km/h  |  %.0f RPM  |  Combustible %.0f%%",speed,rpm,R.num(R.call(Mechanics.class,"fuel",v))*100));R.set(label,"visible",driver(v));}
}
